    if (Z1 == 12 && A1 == 24 && Z2 == 2 && A2 == 4) { return 12; }  // Mg24_He4_to_Si28
    if (Z1 == 14 && A1 == 28 && Z2 == 2 && A2 == 4) { return 13; }  // Si28_He4_to_S32
    if (Z1 == 16 && A1 == 32 && Z2 == 2 && A2 == 4) { return 14; }  // S32_He4_to_Ar36
    if (Z1 == 18 && A1 == 36 && Z2 == 2 && A2 == 4) { return 15; }  // Ar36_He4_to_Ca40
